<?php

namespace Ecompetence\EcompetenceBundle\Repository;
Use Doctrine\ORM\Query\Expr\Join;
/**
 * ExperienceRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class ExperienceRepository extends \Doctrine\ORM\EntityRepository
{
    /*---------------------------------------------------------------Ecompetence*/
 public function findProfileByParametres($data,$data1=null){
   
                
             
            $qb = $this->createQueryBuilder('exp')
            ->select('a')
            ->leftJoin('AgentBundle:Agent', 'a', Join::WITH,'a.id = exp.agent') 
            ->leftJoin('AgentBundle:Emploi', 'e', Join::WITH,'a.Emploi = e.id')
            ->leftJoin('AgentBundle:Fonction', 'fonct', Join::WITH,'exp.fonction = fonct.id')       
            ->leftJoin('EcompetenceBundle:Formation', 'f', Join::WITH,'f.agent = a.id')
            ->leftJoin('EcompetenceBundle:Agent_Langue', 'al', Join::WITH,'al.agent = a.id')
            ->leftJoin('EcompetenceBundle:Langue', 'l', Join::WITH,'al.langue = l.id')
            ->leftJoin('EcompetenceBundle:Agentcompetence', 'ac', Join::WITH,'ac.agent = a.id')
            ->leftJoin('EcompetenceBundle:Domaine', 'd', Join::WITH,'ac.competence = d.id');
            $qb->where('a.matricule is not null');
            
            
             if ($data['poste'] != ''){
                    $qb->andWhere('fonct.id = :poste')
                    ->setParameter('poste',$data['poste']);
            }
            if ($data['emploi'] != ''){
                    $qb->andWhere('e.id = :emploi')
                    ->setParameter('emploi',$data['emploi']);
            }
            if ($data['diplome'] != ''){
                    $qb->andWhere('f.diplome = :diplome')
                    ->setParameter('diplome',$data['diplome']);
            }
             if ($data1!= null){
                    $qb->andWhere('d.id in (:domaine)')
                    ->setParameter('domaine',$data1);
                    
            }
            
   
            $qb->orderBy('a.nom')
           
                  
          /*  ->where("a.matAgent=:matriculemodif")
            ->setparameter("matriculemodif",$matricule)*/;
    
               // ;
        return $qb->getQuery()->getResult();
    }
    
 public function findDateMin($id){
   
                
             
            $qb = $this->createQueryBuilder('exp')
            ->innerJoin('AgentBundle:Agent', 'a', Join::WITH,'a.id = exp.agent') 
            ->Where('a.id = :id')
            ->setParameter('id',$id)       
            ->orderBy('exp.id','ASC')
            ->setMaxResults(1);
               
        
        return $qb->getQuery()->getResult();
    }
 public function findDateMax($id){
   
                
             
            $qb = $this->createQueryBuilder('exp')
         
            ->innerJoin('AgentBundle:Agent', 'a', Join::WITH,'a.id = exp.agent') 
            ->Where('a.id = :id')
            ->setParameter('id',$id)       
            ->orderBy('exp.id','DESC')
            ->setMaxResults(1);  
        
        return $qb->getQuery()->getResult();
    }
    

}